// Migration du Zap "Demande de fournitures" (Typeform -> Gmail).
//
// Le formulaire pose, pour chaque produit, une question "Avez-vous besoin de X ?"
// suivie d'une question "Combien d'unite(s) souhaitez-vous commander ?".
// Les 6 questions "Combien..." ont le MEME intitule -> impossible de les
// distinguer par titre. On lit donc les reponses BRUTES et on rattache chaque
// quantite au produit de la question "Avez-vous besoin de..." qui la precede.
//
// PREREQUIS : dans le noeud "Typeform Trigger", regler
//   Simplify Answers = OFF   et   Only Answers = OFF
// sinon n8n aplatit les reponses et fusionne les 6 quantites.

const body = $input.first().json;
const root = body.form_response || body;
const fields  = (root && root.definition && root.definition.fields) || body.definition && body.definition.fields || [];
const answers = (root && root.answers) || body.answers || [];

if (!fields.length || !answers.length) {
  throw new Error(
    'Reponses Typeform brutes introuvables. Dans le noeud "Typeform Trigger", ' +
    'mets "Simplify Answers" = OFF et "Only Answers" = OFF, puis relance. ' +
    'Cles recues : ' + JSON.stringify(Object.keys(body))
  );
}

// Valeur lisible d'une reponse Typeform quel que soit son type.
function answerValue(a) {
  if (!a) return '';
  switch (a.type) {
    case 'text': return a.text;
    case 'number': return a.number;
    case 'email': return a.email;
    case 'phone_number': return a.phone_number;
    case 'url': return a.url;
    case 'boolean': return a.boolean ? 'oui' : 'non';
    case 'date': return a.date;
    case 'choice': return (a.choice && (a.choice.label || a.choice.other)) || '';
    case 'choices': return ((a.choices && a.choices.labels) || []).join(', ');
    default: return a[a.type] != null ? a[a.type] : '';
  }
}

// Reponses rangees dans l'ordre d'affichage du formulaire.
const byId = {};
answers.forEach(a => { if (a.field && a.field.id) byId[a.field.id] = a; });
const ordered = fields
  .map(f => ({ title: f.title || '', answer: byId[f.id] }))
  .filter(x => x.answer);

const norm = s => (s || '').toLowerCase();

// Premiere reponse dont le titre contient le mot-cle (champs uniques).
function byKeyword() {
  const kws = Array.prototype.slice.call(arguments);
  const m = ordered.find(x => kws.some(k => norm(x.title).includes(k)));
  return m ? answerValue(m.answer) : '';
}

const campus    = byKeyword('campus');
const demandeur = byKeyword('demandeur');
const remarques = byKeyword('remarque', 'complementaire', 'complémentaire');

// Produits, dans l'ordre du mail d'origine. `match` detecte la question
// "Avez-vous besoin de..." correspondante.
const produits = [
  { label: 'ordinateur(s)',      match: t => t.includes('ordinateur') },
  { label: 'double(s) écran(s)', match: t => t.includes('ecran') || t.includes('écran') },
  { label: 'souris',             match: t => t.includes('souris') },
  { label: 'clavier(s)',         match: t => t.includes('clavier') },
  { label: 'casque(s)',          match: t => t.includes('casque') },
  { label: 'Chaise(s)',          match: t => t.includes('chaise') },
];

// Parcours dans l'ordre : chaque "Combien..." herite du dernier produit vu.
const qtyByLabel = {};
let current = null;
for (const item of ordered) {
  const t = norm(item.title);
  if (t.startsWith('avez-vous besoin')) {
    const p = produits.find(pr => pr.match(t));
    current = p ? p.label : null;
  } else if (t.startsWith('combien')) {
    if (current) qtyByLabel[current] = answerValue(item.answer);
  }
}

const lignes = produits
  .map(p => {
    const q = qtyByLabel[p.label];
    return `- ${q != null && q !== '' ? q : 0} ${p.label}`;
  })
  .join('\n');

const subject = `Demande de fournitures - ${campus}`;

const message =
`Hello Julie,

${demandeur} a fait une demande pour le campus de ${campus}.

Il faut acheter :
${lignes}

Remarques supplémentaires :
${remarques}

Bonne journée.`;

return [{ json: { to: 'julie@athena-bs.fr', subject, message, campus, demandeur } }];
